package net.civeira.phylax.features.notification.outbox.application.usecase.enqueue;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.argThat;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.Optional;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;

import jakarta.enterprise.event.Event;
import net.civeira.phylax.features.document.rendering.application.usecase.render.TemplateRenderUsecase;
import net.civeira.phylax.features.document.rendering.domain.RenderedTemplate;
import net.civeira.phylax.features.document.template.domain.TemplateChannelOptions;
import net.civeira.phylax.features.notification.message.domain.Message;
import net.civeira.phylax.features.notification.message.domain.gateway.MessageWriteRepositoryGateway;
import net.civeira.phylax.features.notification.message.infrastructure.event.MessageEventDispatcher;
import net.civeira.phylax.features.notification.outbox.domain.event.UrgentMessageEnqueuedEvent;

/**
 * Unit tests for {@link EnqueueNotificationUseCase}.
 */
class EnqueueNotificationUseCaseTest {

  @Mock
  private TemplateRenderUsecase renderUsecase;

  @Mock
  private MessageWriteRepositoryGateway messageGateway;

  @Mock
  private MessageEventDispatcher eventDispatcher;

  private EnqueueNotificationUseCase useCase;

  @Mock
  private Event<UrgentMessageEnqueuedEvent> events;

  @BeforeEach
  void setUp() {
    MockitoAnnotations.openMocks(this);
    useCase = new EnqueueNotificationUseCase(renderUsecase, messageGateway, eventDispatcher,
        new ObjectMapper(), events);
  }

  @Test
  @DisplayName("enqueue renders template and persists message with tenant")
  void enqueue_withTenant_rendersAndPersistsMessage() {
    RenderedTemplate rendered = renderedTemplate("Subject", "<p>Hello</p>", "Hello");
    when(renderUsecase.render(any())).thenReturn(Optional.of(rendered));
    Message saved = mock(Message.class);
    when(messageGateway.create(any())).thenReturn(saved);

    EnqueueNotificationCommand cmd = EnqueueNotificationCommand.builder().templateCode("WELCOME")
        .channel("MAIL").tenant("tenant-1").recipient("user@example.com")
        .variables(Map.of("name", "Alice")).build();

    Message result = useCase.enqueue(cmd);

    assertEquals(saved, result);
    verify(renderUsecase).render(argThat(input -> "WELCOME".equals(input.getCode())
        && TemplateChannelOptions.MAIL == input.getChannel() && input.getTenant().isPresent()
        && "tenant-1".equals(input.getTenant().get().getUid())));
    verify(messageGateway).create(any());
    verify(eventDispatcher).dispatch(saved);
  }

  @Test
  @DisplayName("enqueue works without tenant (global template)")
  void enqueue_withoutTenant_rendersAndPersistsMessage() {
    RenderedTemplate rendered = renderedTemplate("Subj", "<p>Body</p>", null);
    when(renderUsecase.render(any())).thenReturn(Optional.of(rendered));
    Message saved = mock(Message.class);
    when(messageGateway.create(any())).thenReturn(saved);

    EnqueueNotificationCommand cmd = EnqueueNotificationCommand.builder().templateCode("WELCOME")
        .channel("MAIL").recipient("user@example.com").build();

    useCase.enqueue(cmd);

    verify(renderUsecase).render(argThat(input -> input.getTenant().isEmpty()));
  }

  @Test
  @DisplayName("enqueue throws NoSuchElementException when no template matches")
  void enqueue_throwsWhenTemplateNotFound() {
    when(renderUsecase.render(any())).thenReturn(Optional.empty());

    EnqueueNotificationCommand cmd = EnqueueNotificationCommand.builder().templateCode("MISSING")
        .channel("MAIL").recipient("user@example.com").build();

    assertThrows(NoSuchElementException.class, () -> useCase.enqueue(cmd));
  }

  @Test
  @DisplayName("enqueue falls back to raw HTML when JSON serialisation fails")
  void enqueue_fallsBackToRawHtmlOnJsonFailure() throws JsonProcessingException {
    RenderedTemplate rendered = renderedTemplate("S", "<p>Hi</p>", null);
    when(renderUsecase.render(any())).thenReturn(Optional.of(rendered));
    Message saved = mock(Message.class);
    when(messageGateway.create(any())).thenReturn(saved);

    ObjectMapper failingMapper = mock(ObjectMapper.class);
    doThrow(new JsonProcessingException("forced") {}).when(failingMapper).writeValueAsString(any());

    EnqueueNotificationUseCase useCaseWithBrokenMapper = new EnqueueNotificationUseCase(
        renderUsecase, messageGateway, eventDispatcher, failingMapper, events);

    useCaseWithBrokenMapper.enqueue(EnqueueNotificationCommand.builder().templateCode("T")
        .channel("MAIL").recipient("u@e.com").build());

    // Verify content stored is raw HTML (not JSON)
    ArgumentCaptor<Message> captor = ArgumentCaptor.forClass(Message.class);
    verify(messageGateway).create(captor.capture());
    // Content will be the raw html from the fallback path
    // (Message.create wraps the changeSet so we can't directly inspect content here,
    // but the fact that create was called proves the fallback did not throw)
  }

  @Test
  @DisplayName("enqueue flattens nested variables to dotted notation")
  void enqueue_flattensNestedVariables() {
    RenderedTemplate rendered = renderedTemplate("S", "<p>Hi</p>", null);
    when(renderUsecase.render(any())).thenReturn(Optional.of(rendered));
    when(messageGateway.create(any())).thenReturn(mock(Message.class));

    Map<String, Object> nested = Map.of("user", Map.of("name", "Alice", "age", 30));

    EnqueueNotificationCommand cmd = EnqueueNotificationCommand.builder().templateCode("T")
        .channel("MAIL").recipient("u@e.com").variables(nested).build();

    useCase.enqueue(cmd);

    verify(renderUsecase).render(argThat(input -> {
      Map<String, String> vars = input.getVariables();
      return "Alice".equals(vars.get("user.name")) && "30".equals(vars.get("user.age"));
    }));
  }

  @Test
  @DisplayName("enqueue sets scheduled sendAt from command")
  void enqueue_setsScheduledSendAt() {
    OffsetDateTime sendAt = OffsetDateTime.now(ZoneOffset.UTC).plusHours(1);
    RenderedTemplate rendered = renderedTemplate("S", "<p>Hi</p>", null);
    when(renderUsecase.render(any())).thenReturn(Optional.of(rendered));
    when(messageGateway.create(any())).thenReturn(mock(Message.class));

    EnqueueNotificationCommand cmd = EnqueueNotificationCommand.builder().templateCode("T")
        .channel("MAIL").recipient("u@e.com").sendAt(sendAt).build();

    useCase.enqueue(cmd);

    verify(messageGateway).create(any()); // message was created (sendAt is set via changeSet)
  }

  @Test
  @DisplayName("enqueue skips null values in variable map when flattening")
  void enqueue_skipsNullValuesInVariables() {
    RenderedTemplate rendered = renderedTemplate("S", "<p>Hi</p>", null);
    when(renderUsecase.render(any())).thenReturn(Optional.of(rendered));
    when(messageGateway.create(any())).thenReturn(mock(Message.class));

    Map<String, Object> vars = new java.util.HashMap<>();
    vars.put("key", null);
    vars.put("other", "value");

    EnqueueNotificationCommand cmd = EnqueueNotificationCommand.builder().templateCode("T")
        .channel("MAIL").recipient("u@e.com").variables(vars).build();

    useCase.enqueue(cmd);

    verify(renderUsecase).render(argThat(input -> {
      Map<String, String> flat = input.getVariables();
      return !flat.containsKey("key") && "value".equals(flat.get("other"));
    }));
  }

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------

  private RenderedTemplate renderedTemplate(String subject, String html, String text) {
    RenderedTemplate rendered = mock(RenderedTemplate.class);
    when(rendered.getSubject()).thenReturn(Optional.ofNullable(subject));
    when(rendered.getHtmlContent()).thenReturn(html);
    when(rendered.getTextContent()).thenReturn(Optional.ofNullable(text));
    return rendered;
  }
}
